Definition 1. Fix a type $\sigma$ of size $k$, assume that integers $\ell, \ell_{1}, \ldots, \ell_{t} \geq k$ are such that


\begin{equation*}
\ell_{1}+\cdots+\ell_{t}-k(t-1) \leq \ell, \tag{1}
\end{equation*}


and $F=(M, \theta) \in \mathcal{F}_{\ell}^{\sigma}, F_{1} \in \mathcal{F}_{\ell_{1}}^{\sigma}, \ldots, F_{t} \in \mathcal{F}_{\ell_{t}}^{\sigma}$ are $\sigma$-flags. We define the (key) quantity $p\left(F_{1}, \ldots, F_{t} ; F\right) \in[0,1]$ as follows. Choose in $V(M)$ uniformly at random a sunflower $\left(\boldsymbol{V}_{\mathbf{1}}, \ldots, \boldsymbol{V}_{\boldsymbol{t}}\right)$ with center $\operatorname{im}(\theta)$ and petals of sizes $\ell_{1}, \ldots, \ell_{t}$, respectively (the inequality (1) ensures that such sunflowers do exist). We let $p\left(F_{1}, \ldots, F_{t} ; F\right)$ denote the probability of the event " $\forall i \in[t]\left(\left.F\right|_{\boldsymbol{V}_{i}} \approx F_{i}\right)$ ". When $t=1$, we use the notation $p\left(F_{1}, F\right)$ instead of $p\left(F_{1} ; F\right)$.

Lemma 2.1.

\begin{itemize}
  \item[a)] $p\left(1_{\sigma}, F_{1}, \ldots, F_{t} ; F\right)=p\left(F_{1}, \ldots, F_{t} ; F\right)$ and $p\left(1_{\sigma}, F\right)=1$.
  \item[b)] For $F, F^{\prime} \in \mathcal{F}_{\ell}^{\sigma}, p\left(F, F^{\prime}\right)=1$ if $F=F^{\prime}$ and $p\left(F, F^{\prime}\right)=0$ otherwise.
  \item[c)] $p\left(F_{1}, \ldots, F_{t} ; F\right)=p\left(F_{\gamma(1)}, \ldots, F_{\gamma(t)} ; F\right)$ for any permutation $\gamma \in S_{t}$.
\end{itemize}

Let $\mathcal{K}^{\sigma}$ be its linear subspace generated by all elements of the form


\begin{equation*}
\widetilde{F}-\sum_{F \in \mathcal{F}_{\ell}^{\sigma}} p(\widetilde{F}, F) F, \tag{4}
\end{equation*}


where $\widetilde{F} \in \mathcal{F}_{\tilde{\ell}}^{\sigma}$ and $|\sigma| \leq \tilde{\ell} \leq \ell$.

Introduce the bilinear mapping $\left(\mathbb{R} \mathcal{F}^{\sigma}\right) \otimes\left(\mathbb{R} \mathcal{F}^{\sigma}\right) \longrightarrow \mathcal{A}^{\sigma}, f \otimes g \mapsto f \cdot g$ as follows. For two $\sigma$-flags $F_{1} \in \mathcal{F}_{\ell_{1}}^{\sigma}, F_{2} \in \mathcal{F}_{\ell_{2}}^{\sigma}$ choose arbitrarily $\ell \geq \ell_{1}+\ell_{2}-|\sigma|$ and let


\begin{equation*}
F_{1} \cdot F_{2} \stackrel{\text { def }}{=} \sum_{F \in \mathcal{F}_{\ell}^{\sigma}} p\left(F_{1}, F_{2} ; F\right) F . \tag{5}
\end{equation*}


Extend this mapping onto the whole $\left(\mathbb{R} \mathcal{F}^{\sigma}\right) \otimes\left(\mathbb{R} \mathcal{F}^{\sigma}\right)$ by linearity.

Lemma 2.4.

\begin{itemize}
  \item[a)] The right-hand side of (5) does not depend on the choice of $\ell$ (modulo $\mathcal{K}^{\sigma}$ ).
  \item[b)] (5) induces a bilinear mapping $\mathcal{A}^{\sigma} \otimes \mathcal{A}^{\sigma} \longrightarrow \mathcal{A}^{\sigma}$.
\end{itemize}

\begin{itemize}
  \item[c)] Let $\ell \geq \ell_{1}+\cdots+\ell_{t}-k(t-1)$. Then for $F_{i} \in \mathcal{F}_{\ell_{i}}^{\sigma}(1 \leq i \leq t)$ we have the identity
$$
\left(\left(F_{1} \cdot F_{2}\right) \cdot F_{3} \ldots\right) \cdot F_{t}=\sum_{F \in \mathcal{F}_{\ell}^{\sigma}} p\left(F_{1}, \ldots, F_{t} ; F\right) F \quad\left(\bmod \mathcal{K}^{\sigma}\right) .
$$
  \item[d)] If $\sigma$ is non-degenerate then the induced mapping $\mathcal{A}^{\sigma} \otimes \mathcal{A}^{\sigma} \longrightarrow \mathcal{A}^{\sigma}$ endows $\mathcal{A}^{\sigma}$ with the structure of a commutative associative algebra with the identity element $1_{\sigma}$.
\end{itemize}

Proof. a). Apply $\llbracket \cdot \rrbracket_{\sigma, \eta}$ to the relation (4) and expand $\left.\widetilde{F}\right|_{\eta}$ in the result as a linear combination of $F^{\prime} \in \mathcal{F}_{\ell}^{\left.\sigma\right|_{\eta}}$ using the respective relation in the algebra $\mathcal{A}^{\left.\sigma\right|_{\eta}}$. Comparing coefficients in front of every particular $F^{\prime} \in \mathcal{F}_{\ell}^{\left.\sigma\right|_{\eta}}$, we only have to prove that for every fixed $\widetilde{F} \in \mathcal{F}_{\tilde{\ell}}^{\sigma}$ and $F^{\prime} \in \mathcal{F}_{\ell}^{\left.\sigma\right|_{\eta}}$, we have

\begin{figure}[h]
\begin{center}
\captionsetup{labelformat=empty}
\caption{Theorem 2.5. a) $\llbracket \cdot \rrbracket_{\sigma, \eta}$ takes $\mathcal{K}^{\sigma}$ to $\mathcal{K}^{\left.\sigma\right|_{\eta}}$ and thus defines a linear mapping $\mathcal{A}^{\sigma} \rightarrow \mathcal{A}^{\left.\sigma\right|_{\eta}}$.}

\begin{equation*}
p\left(\left.\widetilde{F}\right|_{\eta}, F^{\prime}\right) \cdot q_{\sigma, \eta}(\widetilde{F})=\sum_{\substack{F \in \mathcal{F}_{\ell}^{\sigma} \\ F \mid \eta=F^{\prime}}} q_{\sigma, \eta}(F) p(\widetilde{F}, F) . \tag{6}
\end{equation*}
\end{center}
\end{figure}

For doing that, we (as in the proof of Lemma 2.2) calculate the probability of the same event in two different ways. Namely, let $F^{\prime}=\left(M, \theta^{\prime}\right)$. Pick a pair $(\tilde{\boldsymbol{V}}, \boldsymbol{\theta})$, where $\boldsymbol{\theta}:[k] \longrightarrow V(M)$ is an injective function and $\tilde{\boldsymbol{V}} \subseteq V(M),|\widetilde{\boldsymbol{V}}|=\ell$ uniformly at random, but subject to two additional restrictions $\boldsymbol{\theta} \eta=\theta^{\prime}$ and $\widetilde{\boldsymbol{V}} \supseteq \operatorname{im}(\boldsymbol{\theta})$. Then both sides of (6) calculate the probability of the event " $\boldsymbol{\theta}$ is a model embedding $\sigma \longrightarrow M$ and the $\sigma$-flag $\left(\left.M\right|_{\tilde{\boldsymbol{V}}}, \boldsymbol{\theta}\right)$ is isomorphic to $\widetilde{F}^{\prime \prime}$ (the right-hand side splits this event according to the isomorphism type of $(M, \boldsymbol{\theta}))$.\\
b) and c) are straightforward.

Definition 3. Let $T_{1}$ and $T_{2}$ be two universal first-order theories with equality in (possibly different) languages $L_{1}$ and $L_{2}$. We assume that $L_{1}$ and $L_{2}$ do not contain function symbols, but, along with predicate symbols, we also allow constants. Let $U(x)$ be an open formula in the language $L_{2}$ such that $T_{2} \vdash U(c)$ for every constant $c \in L_{2}$, and $I$ be a translation that takes every predicate symbol $P\left(x_{1}, \ldots, x_{r}\right) \in L_{1}$ to an open formula $I(P)\left(x_{1}, \ldots, x_{r}\right)$ in the language $L_{2}$, and takes every constant $c \in L_{1}$ to a constant $I(c) \in L_{2} . I$ is extended to open formulas of the language $L_{1}$ by declaring that it commutes with logical connectives. The pair $(U, I)$ is an open interpretation of $T_{1}$ in $T_{2}$, denoted $(U, I): T_{1} \leadsto T_{2}$ if for every axiom $\forall x_{1}, \ldots, x_{n} A\left(x_{1}, \ldots, x_{n}\right)$ of $T_{1}$ we have


\begin{equation*}
T_{2} \vdash \forall x_{1}, \ldots, x_{n}\left(\left(U\left(x_{1}\right) \wedge \ldots \wedge U\left(x_{n}\right)\right) \Longrightarrow I(A)\left(x_{1}, \ldots, x_{n}\right)\right) . \tag{7}
\end{equation*}

We now introduce the special element $u$ that is the sum of all $\sigma_{2}$-flags on $k_{2}+1$ vertices whose only non-labelled vertex satisfies $U$ :


\begin{equation*}
u \stackrel{\text { def }}{=} \sum\left\{F \mid F \in \mathcal{F}_{k_{2}+1}^{\sigma_{2}, U}\left[T_{2}\right]\right\}, \tag{8}
\end{equation*}


and assume that


\begin{equation*}
u \text { is not a zero divisor in } \mathcal{A}^{\sigma_{2}}\left[T_{2}\right] \text {. } \tag{9}
\end{equation*}

In this notation, the homomorphism $\pi^{\sigma, \eta}: \mathcal{A}^{\left.\sigma\right|_{\eta}} \longrightarrow \mathcal{A}^{\sigma}$ can be calculated as


\begin{equation*}
\pi^{\sigma, \eta}(F) \stackrel{\text { def }}{=} \sum\left\{\widehat{F} \in \mathcal{F}_{\ell+d}^{\sigma}|\widehat{F}|_{\eta}=F\right\}\left(F \in \mathcal{F}_{\ell}^{\left.\sigma\right|_{\eta}}\right) . \tag{10}
\end{equation*}

Note that in $\mathcal{A}^{\sigma}$ we have


\begin{equation*}
\sum_{F \in \mathcal{F}_{\ell}^{\sigma}} F=1_{\sigma}(\ell \geq|\sigma|) \tag{11}
\end{equation*}


(which is a special case of (4)), therefore for every $\phi \in \operatorname{Hom}^{+}\left(\mathcal{A}^{\sigma}, \mathbb{R}\right)$ and every $F \in \mathcal{F}^{\sigma}$ we actually have $\phi(F) \in[0,1]$.

Theorem 3.1. a) Let $\sigma$ be a non-degenerate type of size $k$, and $\eta:\left[k^{\prime}\right] \longrightarrow$ $[k]$ be an injective mapping. Then

$$
\llbracket \mathcal{C}_{\mathrm{sem}}\left(\mathcal{F}^{\sigma}\right) \rrbracket_{\sigma, \eta} \subseteq \mathcal{C}_{\mathrm{sem}}\left(\mathcal{F}^{\sigma \mid{ }_{\eta}}\right) .
$$

b) In the set-up of Definition 4, let $f \in \mathcal{C}_{\operatorname{sem}}\left(\mathcal{F}^{\sigma_{1}}\left[T_{1}\right]\right)$. Then for every integer $\ell$ such that


\begin{equation*}
u^{\ell} \cdot \pi^{(U, I)}(f) \in \mathbb{R} \mathcal{F}^{\sigma_{2}, U}\left[T_{2}\right], \tag{12}
\end{equation*}


we have $u^{\ell} \cdot \pi^{(U, I)}(f) \in \mathcal{C}_{\text {sem }}\left(\mathcal{F}^{\sigma_{2}}\left[T_{2}\right]\right)$.\\
In particular, in the notation of Section 2.3.1,


\begin{equation*}
\pi^{\sigma, \eta}\left(\mathcal{C}_{\mathrm{sem}}\left(\mathcal{F}^{\left.\sigma\right|_{\eta}}\right)\right) \subseteq \mathcal{C}_{\mathrm{sem}}\left(\mathcal{F}^{\sigma}\right), \tag{13}
\end{equation*}


and in the notation of Section 2.3.2,

$$
\begin{aligned}
& \forall f \in \mathcal{C}_{\operatorname{sem}}\left(\mathcal{F}^{\left.\sigma\right|_{\eta}}\right) \forall \ell \in \mathbb{Z} \\
& \quad\left(F_{0}^{\ell} \cdot \pi^{F_{0}, \eta}(f) \in \mathbb{R} \mathcal{F}^{\sigma, F_{0}} \Longrightarrow F_{0}^{\ell} \cdot \pi^{F_{0}, \eta}(f) \in \mathcal{C}_{\operatorname{sem}}\left(\mathcal{F}^{\sigma}\right)\right) .
\end{aligned}
$$

In the set-up of Definition 4, let $f \in \mathcal{C}_{\operatorname{sem}}\left(\mathcal{F}^{\sigma_{1}}\left[T_{1}\right]\right)$. Then for every integer $\ell$ such that


\begin{equation*}
u^{\ell} \cdot \pi^{(U, I)}(f) \in \mathbb{R} \mathcal{F}^{\sigma_{2}, U}\left[T_{2}\right], \tag{12}
\end{equation*}


we have $u^{\ell} \cdot \pi^{(U, I)}(f) \in \mathcal{C}_{\text {sem }}\left(\mathcal{F}^{\sigma_{2}}\left[T_{2}\right]\right)$.\\
In particular, in the notation of Section 2.3.1,


\begin{equation*}
\pi^{\sigma, \eta}\left(\mathcal{C}_{\mathrm{sem}}\left(\mathcal{F}^{\left.\sigma\right|_{\eta}}\right)\right) \subseteq \mathcal{C}_{\mathrm{sem}}\left(\mathcal{F}^{\sigma}\right), \tag{13}
\end{equation*}


and in the notation of Section 2.3.2,

$$
\begin{aligned}
& \forall f \in \mathcal{C}_{\operatorname{sem}}\left(\mathcal{F}^{\left.\sigma\right|_{\eta}}\right) \forall \ell \in \mathbb{Z} \\
& \quad\left(F_{0}^{\ell} \cdot \pi^{F_{0}, \eta}(f) \in \mathbb{R} \mathcal{F}^{\sigma, F_{0}} \Longrightarrow F_{0}^{\ell} \cdot \pi^{F_{0}, \eta}(f) \in \mathcal{C}_{\operatorname{sem}}\left(\mathcal{F}^{\sigma}\right)\right) .
\end{aligned}
$$

Theorem 3.3 ([LoSz]). a) For every convergent sequence $\left\{F_{n}\right\}$ of $\sigma$-flags, $\lim _{n \rightarrow \infty} p^{F_{n}} \in \operatorname{Hom}^{+}\left(\mathcal{A}^{\sigma}, \mathbb{R}\right)$.

\begin{itemize}
  \item[b)] Conversely, every element $\operatorname{Hom}^{+}\left(\mathcal{A}^{\sigma}, \mathbb{R}\right)$ can be represented in the form $\lim _{n \rightarrow \infty} p^{F_{n}}$ for a convergent sequence $\left\{F_{n}\right\}$ of $\sigma$-flags.
\end{itemize}

b). Let $\phi \in \operatorname{Hom}^{+}\left(\mathcal{A}^{\sigma}, \mathbb{R}\right)$. (11) implies that for every $\ell$ the quantities $\phi(F)\left(F \in \mathcal{F}_{\ell}^{\sigma}\right)$ define a probability measure on $\mathcal{F}_{\ell}^{\sigma}$. Consider the product measure on $\prod_{\ell=|\sigma|}^{\infty} \mathcal{F}_{\ell}^{\sigma}$, and choose an increasing sequence $\left\{\boldsymbol{F}_{\boldsymbol{n}}\right\}$, where $\boldsymbol{F}_{\boldsymbol{n}} \in \mathcal{F}_{n^{2}}^{\sigma}$, at random according to this measure (thus, $\boldsymbol{F}_{\boldsymbol{n}}$ are independent for different $n$ ). It is sufficient to show that $\mathbf{P}\left[\lim _{n \rightarrow \infty} p^{\boldsymbol{F}_{\boldsymbol{n}}}=\phi\right]=1$. And, since $\mathcal{F}^{\sigma}$ is countable, it is enough to prove that for every fixed $F \in \mathcal{F}_{\ell}^{\sigma}$ and every fixed $\epsilon>0$,


\begin{equation*}
\mathbf{P}\left[\exists n_{0} \forall n \geq n_{0}\left|p\left(F, \boldsymbol{F}_{\boldsymbol{n}}\right)-\phi(F)\right| \leq \epsilon\right]=1 . \tag{14}
\end{equation*}


For $n^{2} \geq \ell$ we have

$$
\mathbf{E}\left[p\left(F, \boldsymbol{F}_{\boldsymbol{n}}\right)\right]=\sum_{F_{n} \in \mathcal{F}_{n^{2}}^{\sigma}} p\left(F, F_{n}\right) \phi\left(F_{n}\right)=\phi(F)
$$

(since $\phi$ satisfies (4)). Also,

$$
\begin{aligned}
& \operatorname{Var}\left[p\left(F, \boldsymbol{F}_{\boldsymbol{n}}\right)\right]=\mathbf{E}\left[p\left(F, \boldsymbol{F}_{\boldsymbol{n}}\right)^{2}\right]-\phi\left(F^{2}\right) \\
& \quad=\sum_{F_{n} \in \mathcal{F}_{n^{2}}^{\sigma}} p\left(F, F_{n}\right)^{2} \phi\left(F_{n}\right)-\sum_{F_{n} \in \mathcal{F}_{n^{2}}^{\sigma}} p\left(F, F ; F_{n}\right) \phi\left(F_{n}\right)
\end{aligned}
$$

(by (5)) and $\left|p\left(F, F_{n}\right)^{2}-p\left(F, F ; F_{n}\right)\right| \leq O\left(1 / n^{2}\right)$ (uniformly over all choices of $F_{n}$ ) by Lemma 2.3. Thus, $\operatorname{Var}\left[p\left(F, \boldsymbol{F}_{\boldsymbol{n}}\right)\right] \leq O\left(1 / n^{2}\right)$, and (14) follows by a standard application of Chebyshev's inequality and Borel-Cantelli lemma.

\left.\begin{array}{l}
\forall \phi \in \operatorname{Hom}^{+}\left(\mathcal{A}^{\sigma}, \mathbb{R}\right)\left(\left(\phi\left(F_{1}\right), \ldots, \phi\left(F_{h}\right)\right) \in D\right.  \tag{15}\\
\left.\quad \Longrightarrow f\left(\phi\left(F_{1}\right), \ldots, \phi\left(F_{h}\right)\right) \geq 0\right)
\end{array}\right\}

\left.\begin{array}{l}
\liminf _{\ell \rightarrow \infty} \min \left\{f\left(p\left(F_{1}, F\right), \ldots, p\left(F_{h}, F\right)\right) \mid F \in \mathcal{F}_{\ell}^{\sigma}\right.  \tag{16}\\
\left.\quad \wedge\left(p\left(F_{1}, F\right), \ldots, p\left(F_{h}, F\right)\right) \in D\right\} \geq 0
\end{array}\right\}

Assume that $\phi_{0} \in \operatorname{Hom}^{+}\left(\mathcal{A}^{\sigma_{0}}, \mathbb{R}\right)$ has the property ${ }^{2}$ $\phi_{0}((\sigma, \eta))>0$. Let $\mathcal{B}^{\sigma}$ consist of all Borel subsets of $\operatorname{Hom}^{+}\left(\mathcal{A}^{\sigma}, \mathbb{R}\right)$. A probability measure $\mathbf{P}^{\sigma, \eta}$ on $\mathcal{B}^{\sigma}$ extends $\phi_{0}$ if for any $f \in \mathcal{A}^{\sigma}$,


\begin{equation*}
\int_{\operatorname{Hom}^{+}\left(\mathcal{A}^{\sigma}, \mathbb{R}\right)} \phi(f) \mathbf{P}^{\sigma, \eta}(d \phi)=\frac{\phi_{0}\left(\llbracket f \rrbracket_{\sigma, \eta}\right)}{\phi_{0}(\langle\sigma, \eta\rangle)}, \tag{17}
\end{equation*}


where (to improve readability) we have introduced the notation

$$
\langle\sigma, \eta\rangle \stackrel{\text { def }}{=} \llbracket 1_{\sigma} \rrbracket_{\sigma, \eta}=q_{\sigma, \eta}\left(1_{\sigma}\right) \cdot(\sigma, \eta) \in \mathcal{A}^{\left.\sigma\right|_{\eta}}
$$

(cf. Theorem 2.5 b) and Remark 2).

Definition 9. For a $\sigma_{0}$-flag $F=\left(M, \theta^{\prime}\right) \in \mathcal{F}_{\ell}^{\sigma_{0}}$ with $p^{F}((\sigma, \eta))>0$ define a (discrete) probability measure $\mathbf{P}_{F}^{\sigma, \eta}$ on Borel subsets of $[0,1]^{\mathcal{F}^{\sigma}}$ as follows. Choose, uniformly at random, a model embedding $\boldsymbol{\theta}: \sigma \longrightarrow M$ consistent with $\theta^{\prime}$ (that is, $\boldsymbol{\theta} \eta=\theta^{\prime}$ ). Then, for Borel $A \subseteq[0,1]^{\mathcal{F}^{\sigma}}$, we let

$$
\mathbf{P}_{F}^{\sigma, \eta}(A) \stackrel{\text { def }}{=} \mathbf{P}\left[p^{(M, \boldsymbol{\theta})} \in A\right] .
$$

Lemma 3.11. Let $\left\{F_{n}\right\}$ be a convergent sequence of $\sigma_{0}$-flags, and $\phi_{0} \stackrel{\text { def }}{=} \lim _{n \rightarrow \infty} p^{F_{n}}$. Assume that $\phi_{0}((\sigma, \eta))>0$. Then for any flag $F \in \mathcal{F}_{\ell}^{\sigma}$,

$$
\lim _{n \rightarrow \infty} \int_{[0,1]^{\mathcal{F} \sigma}} x(F) \mathbf{P}_{F_{n}}^{\sigma, \eta}(d x)=\frac{\phi_{0}\left(\llbracket F \rrbracket_{\sigma, \eta}\right)}{\phi_{0}(\langle\sigma, \eta\rangle)} .
$$

Proof. $\phi_{0}((\sigma, \eta))>0$ implies $p^{F_{n}}((\sigma, \eta))>0$ for sufficiently large $n$. By Definition 9, as long as $\ell_{n} \geq \ell$ we have


\begin{equation*}
\int_{[0,1]^{\mathcal{F} \sigma}} x(F) \mathbf{P}_{F_{n}}^{\sigma, \eta}(d x)=\mathbf{E}[p(F,(M, \boldsymbol{\theta}))] \tag{18}
\end{equation*}


where $F=(M, \theta)$ and $\boldsymbol{\theta}$ is constructed as in Definition 9. On the other hand, $p^{F_{n}}\left(\llbracket F \rrbracket_{\sigma, \eta}\right)$ is the probability that a random injective mapping $[k] \longrightarrow M$ consistent with $\theta$ on $\operatorname{im}(\eta)$ defines a model embedding and the resulting $\sigma$-flag is\\
isomorphic to $F$. Thus,


\begin{equation*}
\int_{[0,1]^{\mathcal{F} \sigma}} x(F) \mathbf{P}_{F_{n}}^{\sigma, \eta}(d x)=\frac{p^{F_{n}}\left(\llbracket F \rrbracket_{\sigma, \eta}\right)}{p^{F_{n}}(\langle\sigma, \eta\rangle)} . \tag{19}
\end{equation*}


Taking the limit proves Lemma 3.11. $-1$

Proof. $\phi_{0}((\sigma, \eta))>0$ implies $p^{F_{n}}((\sigma, \eta))>0$ for sufficiently large $n$. By Definition 9, as long as $\ell_{n} \geq \ell$ we have


\begin{equation*}
\int_{[0,1]^{\mathcal{F} \sigma}} x(F) \mathbf{P}_{F_{n}}^{\sigma, \eta}(d x)=\mathbf{E}[p(F,(M, \boldsymbol{\theta}))] \tag{18}
\end{equation*}


where $F=(M, \theta)$ and $\boldsymbol{\theta}$ is constructed as in Definition 9. On the other hand, $p^{F_{n}}\left(\llbracket F \rrbracket_{\sigma, \eta}\right)$ is the probability that a random injective mapping $[k] \longrightarrow M$ consistent with $\theta$ on $\operatorname{im}(\eta)$ defines a model embedding and the resulting $\sigma$-flag is\\
isomorphic to $F$. Thus,


\begin{equation*}
\int_{[0,1]^{\mathcal{F} \sigma}} x(F) \mathbf{P}_{F_{n}}^{\sigma, \eta}(d x)=\frac{p^{F_{n}}\left(\llbracket F \rrbracket_{\sigma, \eta}\right)}{p^{F_{n}}(\langle\sigma, \eta\rangle)} . \tag{19}
\end{equation*}


Taking the limit proves Lemma 3.11. $-1$

