\int_{[0,1]^{\mathcal{F} \sigma}} x(F) \mathbf{P}_{F_{n}}^{\sigma, \eta}(d x)=\frac{p^{F_{n}}\left(\llbracket F \rrbracket_{\sigma, \eta}\right)}{p^{F_{n}}(\langle\sigma, \eta\rangle)} . \tag{19}
\end{equation*}

Definition 10. Let $\sigma_{0}$ be a non-degenerate type of size $k_{0}$ and $\phi \in$ $\operatorname{Hom}^{+}\left(\mathcal{A}^{\sigma_{0}}, \mathbb{R}\right)$. An ensemble of random homomorphisms rooted at $\phi$ is a collection of random homomorphisms $\left\{\phi^{\boldsymbol{\sigma}, \boldsymbol{\eta}}\right\}$, where $(\sigma, \eta)$ runs over all extensions of $\sigma_{0}$ with $\phi((\sigma, \eta))>0$, and $\boldsymbol{\phi}^{\boldsymbol{\sigma}, \boldsymbol{\eta}}$ itself is chosen according to some probability measure on $\mathcal{B}^{\sigma}$ such that:


\begin{equation*}
\mathbf{E}\left[\phi^{\sigma, \eta}(f)\right]=\frac{\phi\left(\llbracket f \rrbracket_{\sigma, \eta}\right)}{\phi(\langle\sigma, \eta\rangle)}\left(f \in \mathcal{A}^{\sigma}\right) . \tag{21}
\end{equation*}

Theorem 3.14 (Cauchy-Schwarz inequality).

$$
\llbracket f^{2} \rrbracket_{\sigma, \eta} \cdot \llbracket g^{2} \rrbracket_{\sigma, \eta} \geq_{\left.\sigma\right|_{\eta}} \llbracket f g \rrbracket_{\sigma, \eta}^{2} .
$$

In particular $\left(g=1_{\sigma}\right)$,


\begin{equation*}
\llbracket f^{2} \rrbracket_{\sigma, \eta} \cdot\langle\sigma, \eta\rangle \geq_{\left.\sigma\right|_{\eta}} \llbracket f \rrbracket_{\sigma, \eta}^{2}, \tag{22}
\end{equation*}


which in turn implies


\begin{equation*}
\llbracket f^{2} \rrbracket_{\sigma, \eta} \geq_{\left.\sigma\right|_{\eta}} 0 . \tag{23}
\end{equation*}

Given an arbitrary theory $T$, a non-degenerate type $\sigma, \phi \in \operatorname{Hom}^{+}\left(\mathcal{A}^{0}, \mathbb{R}\right)$ such that $\phi(\sigma)>0$ and $F \in \mathcal{F}^{\sigma}$ we let


\begin{equation*}
\delta_{F}(\phi) \stackrel{\text { def }}{=} \max \left\{a \mid \mathbf{P}\left[\phi^{\boldsymbol{\sigma}}(F)<a\right]=0\right\}=\inf \left\{a \mid \mathbf{P}\left[\phi^{\boldsymbol{\sigma}}(F)<a\right]>0\right\} . \tag{24}
\end{equation*}

Remark 5. Applying Theorem 3.18 to both $f$ and $-f$, we also have its symmetric versions:


\begin{align*}
& \mathbf{P}\left[\phi^{\sigma_{2}, \boldsymbol{\eta}_{2}}(f)=0\right]=1 \Longrightarrow \mathbf{P}\left[\phi^{\sigma_{1}, \boldsymbol{\eta}_{1}}\left(\llbracket f \rrbracket_{\sigma_{2}, \eta}\right)=0\right]=1 \\
& \mathbf{P}\left[\phi^{\sigma_{1}, \boldsymbol{\eta}_{1}}(f)=0\right]=1 \Longrightarrow \mathbf{P}\left[\phi^{\sigma_{2}, \boldsymbol{\eta}_{2}}\left(\pi^{\sigma_{2} \eta}(f)\right)=0\right]=1 \tag{26}
\end{align*}


((26) can be also obtained directly from part b) of that theorem).\\

Theorem 4.3. Let $\vec{M}=\left(M_{1}, \ldots, M_{h}\right) \in \mathcal{M}$ be fixed models of the theory $T$, $\phi_{0} \in \operatorname{Hom}^{+}\left(\mathcal{A}^{0}, \mathbb{R}\right)$, and $f \in C^{1}(U)$, where $U$ is an open neighbourhood of the point $a \stackrel{\text { def }}{=}\left(\phi_{0}\left(M_{1}\right), \ldots, \phi_{0}\left(M_{h}\right)\right) \in \mathbb{R}^{h}$. Assume that for any $\phi \in \operatorname{Hom}^{+}\left(\mathcal{A}^{0}, \mathbb{R}\right)$ such that $\left(\phi\left(M_{1}\right), \ldots, \phi\left(M_{h}\right)\right) \in U$ we have

$$
f\left(\phi\left(M_{1}\right), \ldots, \phi\left(M_{h}\right)\right) \geq f(a) .
$$

Then for the extension $\boldsymbol{\phi}_{\mathbf{0}}^{\mathbf{1}}$ of $\phi_{0}$,


\begin{equation*}
\mathbf{P}\left[\phi_{\mathbf{0}}^{\mathbf{1}}\left(\partial_{1} \operatorname{Grad}_{\vec{M}, a}(f)\right)=0\right]=1 \tag{27}
\end{equation*}


holds.

Proof. Lemma 4.2 c) implies that

$$
\mathbf{E}\left[\phi_{\mathbf{0}}^{\mathbf{1}}\left(\partial_{1} \operatorname{Grad}_{\vec{M}, a}(f)\right)\right]=\phi_{0}\left(\llbracket \partial_{1} \operatorname{Grad}_{\vec{M}, a}(f) \rrbracket_{1}\right)=0 .
$$

Therefore, it suffices to prove (27) only in one direction, and we elect to prove that


\begin{equation*}
\mathbf{P}\left[\boldsymbol{\phi}_{\mathbf{0}}^{\mathbf{1}}\left(\partial_{1} \operatorname{Grad}_{\vec{M}, a}(f)\right) \geq 0\right]=1 . \tag{28}
\end{equation*}


Fix an increasing sequence $\left\{N_{n}\right\}$ of models such that $\lim _{n \rightarrow \infty} p^{N_{n}}=\phi_{0}$. Then by Theorem 3.12 the corresponding sequence of probability measures $\mathbf{P}_{N_{n}}^{1}$ weakly converges to the extension $\mathbf{P}^{1}$ of $\phi_{0}$ (recall that $\mathbf{P}_{N_{n}}^{1}$ corresponds to the random element $p^{\left(N_{n}, \boldsymbol{v}_{\boldsymbol{n}}\right)} \in[0,1]^{\mathcal{F}^{1}}$, where $\boldsymbol{v}_{\boldsymbol{n}}$ is chosen uniformly at random from $\left.V\left(N_{n}\right)\right)$.

Assume now that (28) fails, that is $\mathbf{P}\left[\phi_{\mathbf{0}}^{\mathbf{1}}\left(\partial_{1} \operatorname{Grad}_{\vec{M}, a}(f)\right)<0\right]>0$. Then for some $\epsilon>0$ we have

$$
\mathbf{P}\left[\boldsymbol{\phi}_{\mathbf{0}}^{\mathbf{1}}\left(\partial_{1} \operatorname{Grad}_{\vec{M}, a}(f)\right)<-\epsilon\right]>0,
$$

and since the set $\left\{\phi \in \operatorname{Hom}^{+}\left(\mathcal{A}^{1}, \mathbb{R}\right) \mid \phi\left(\partial_{1} \operatorname{Grad}_{\vec{M}, a}\right)<-\epsilon\right\}$ is open, we can apply Theorem 3.9 and conclude that

$$
\mathbf{P}\left[p^{\left(N_{n}, \boldsymbol{v}_{n}\right)}\left(\partial_{1} \operatorname{Grad}_{\vec{M}, a}(f)\right)<-\epsilon\right] \geq \epsilon^{\prime}
$$

for some absolute constants $\epsilon, \epsilon^{\prime}>0$, and for all sufficiently large $n$.\\
Fix now a sufficiently small positive constant $\delta<\epsilon^{\prime}$ (to be specified later in the course of the proof). Let $\ell_{n} \stackrel{\text { def }}{=}\left|V\left(N_{n}\right)\right|, m_{n} \stackrel{\text { def }}{=}\left\lfloor\delta \ell_{n}\right\rfloor$, and choose arbitrarily an $m_{n}$-subset $V_{n} \subseteq V\left(N_{n}\right)$ such that


\begin{equation*}
