\end{equation*}


Since also $\frac{1}{\ell_{n}-i+1} \leq O\left(1 / \ell_{n}\right)$ and $\left|\frac{1}{\ell_{n}-i+1}-\frac{1}{\ell_{n}}\right| \leq O\left(\delta / \ell_{n}\right)$, we get

$$
\left|\frac{1}{\ell_{n}-i+1} p^{\left(N_{n, i-1}, v_{i}\right)}\left(\partial_{1} M\right)-\frac{1}{\ell_{n}} p^{\left(N_{n}, v_{i}\right)}\left(\partial_{1} M\right)\right| \leq O\left(\delta / \ell_{n}\right),
$$

